// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address caller, uint256 amount, uint256 initialBalance) public {
        vm.assume(caller != address(0));
        vm.assume(initialBalance <= type(uint256).max - amount);
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.addToBalance{value: initialBalance}();
        uint256 balanceBefore = c.getBalance(caller);
        assertEq(balanceBefore, initialBalance);
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 balanceAfter = c.getBalance(caller);
        assertEq(balanceAfter, balanceBefore + amount);
    }
}
